#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>p(n+1);
for(int i=1;i<=n;++i)scanf("%lld",&p[i]);
vector<long long>dp(n+1,0);
for(int i=1;i<=n;++i){
long long best=p[i];
for(int j=1;j<i;++j)best=max(best,dp[j]+dp[i-j]);
dp[i]=best;}
printf("%lld\n",dp[n]);return 0;}

